$ErrorActionPreference="Stop"\nWrite-Host "ReturnShield diagnostics"\nforeach($port in 8000,8501){\n  $c=Get-NetTCPConnection -LocalPort $port -State Listen -ErrorAction SilentlyContinue\n  if($c){ Write-Host "Port $port is LISTENING (PID(s): $($c.OwningProcess -join ', '))" } else { Write-Host "Port $port is free" }\n}\ntry { $m=Invoke-RestMethod "http://127.0.0.1:8000/api/v1/meta"; Write-Host "API meta:"; $m | Format-List } catch { Write-Host "API meta unavailable: $($_.Exception.Message)" }\ntry { $r=Invoke-RestMethod "http://127.0.0.1:8000/api/v1/returns?limit=3"; Write-Host "Live returns route OK. Total=$($r.total), Rows=$($r.data.Count)" } catch { Write-Host "Live returns route FAILED: $($_.Exception.Message)" }\n